SECD_HELP = [
    "# secdeep - الأمان وسحابة جوجل العميقة: تشفير وتوكنات وواجهات API (cryptography / google)",
]

_SECD_TOKEN = re.compile(
    r"(?P<dot>\.)?"
    r"(?P<word>(?!\d)[\w\u064B-\u065F\u0670]+)"
    r"(?P<open>\s*\()?"
)

USER_NAMES = set()


def _secdeep_replace(match):
    dot = match.group("dot")
    word = match.group("word")
    open_paren = match.group("open")
    if word in USER_NAMES:
        return match.group(0)
    if dot:
        return match.group(0)
    if word in SECD_CONSTS:
        return SECD_CONSTS[word]
    if word in SECD_FUNCS:
        return SECD_FUNCS[word] + (open_paren or "")
    return match.group(0)


def SECD_SUBSTITUTE(text):
    """يترجم كلمات المكتبة في نص واحد ويُرجع المترجم."""
    if not text:
        return text
    return _SECD_TOKEN.sub(_secdeep_replace, text)
